package br.gov.go.ppgo.espp.domain;import jakarta.persistence.*;import java.time.OffsetDateTime;
@Entity @Table(name="ESPP_IDENTIDADE_VISUAL") public class IdentidadeVisual{@Id @Column(length=40)private String chave;@Lob @Column(nullable=false)private byte[] conteudo;@Column(name="CONTENT_TYPE",nullable=false,length=60)private String contentType;@Column(name="ATUALIZADO_EM",nullable=false)private OffsetDateTime atualizadoEm;@Column(name="ATUALIZADO_POR",length=160)private String atualizadoPor;public IdentidadeVisual(){}public String getChave(){return chave;}public byte[] getConteudo(){return conteudo;}public String getContentType(){return contentType;}public void atualizar(String k,byte[]c,String t,String a){chave=k;conteudo=c;contentType=t;atualizadoPor=a;atualizadoEm=OffsetDateTime.now();}}
